package net.atlasauth.pca.verifier

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/** The lenient canonical form against canonical-number-vectors.json (generated by the TS reference rules): ES Number::toString, JSON.stringify strings, UTF-8 key order. */
@Suppress("UNCHECKED_CAST")
class CanonicalVectorsTest {
    @Test
    fun everyVectorMatchesTheReference() {
        val cases = ParityVectors.load("canonical-number-vectors.json")["cases"] as List<Map<String, Any?>>
        assertTrue(cases.size >= 50)
        for (c in cases) {
            val json = c["json"] as String
            assertEquals(json, c["expect"], Json.canonicalize(Json.parseLenient(json)))
        }
    }

    @Test
    fun esNumberFormsPinnedInline() {
        assertEquals("1e+21", Json.esNumber(1e21))
        assertEquals("100000000000000000000", Json.esNumber(1e20))
        assertEquals("1e-7", Json.esNumber(1e-7))
        assertEquals("0.000001", Json.esNumber(1e-6))
        assertEquals("-1.5e-7", Json.esNumber(-1.5e-7))
        assertEquals("5e-324", Json.esNumber(java.lang.Double.MIN_VALUE))
        assertEquals("1.7976931348623157e+308", Json.esNumber(Double.MAX_VALUE))
        assertEquals("0.30000000000000004", Json.esNumber(0.1 + 0.2))
    }
}
